// Rapport hebdomadaire déterministe — aucun appel IA ici (contrainte du lot).
// Utilise uniquement les données Supabase (projects, tasks, meetings) via
// l'API REST (service_role, bypass RLS) et l'API admin Supabase Auth pour
// l'e-mail de connexion de chaque utilisateur.
//
// Hypothèses documentées (voir README > Limites) :
//  - "tâches créées" = tâches dont created_at est dans les 7 derniers jours
//    (la semaine qui vient de se terminer, en heure Toronto).
//  - "échéances de la semaine" / "réunions de la semaine" = les 7 prochains
//    jours à partir d'aujourd'hui (lundi), donc la semaine qui commence.
//  - Pagination Supabase Auth admin : une seule page (par défaut 50
//    utilisateurs) est récupérée. Voir README > Limites pour une instance
//    avec plus d'utilisateurs.
//  - Une erreur pour UN utilisateur (Supabase indisponible, données
//    inattendues, etc.) est journalisée puis ignorée : elle ne bloque pas
//    la génération des rapports des autres utilisateurs.

const SUPABASE_URL = $env.SUPABASE_URL;
const SERVICE_ROLE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const APP_BASE_URL = $env.APP_BASE_URL || "";
const TZ = "America/Toronto";

if (!SUPABASE_URL || !SERVICE_ROLE_KEY) {
  throw new Error(
    "SUPABASE_URL et SUPABASE_SERVICE_ROLE_KEY doivent être définis comme variables d'environnement sur l'instance n8n."
  );
}

function authHeaders() {
  return {
    apikey: SERVICE_ROLE_KEY,
    Authorization: `Bearer ${SERVICE_ROLE_KEY}`,
  };
}

async function restGet(path, query) {
  const qs = new URLSearchParams(query).toString();
  const url = `${SUPABASE_URL}/rest/v1/${path}${qs ? `?${qs}` : ""}`;
  return this.helpers.httpRequest({
    method: "GET",
    url,
    headers: authHeaders(),
    json: true,
  });
}

async function listAuthUsers() {
  // Une seule page (limite par défaut de l'API admin) — voir README > Limites.
  const url = `${SUPABASE_URL}/auth/v1/admin/users`;
  const res = await this.helpers.httpRequest({
    method: "GET",
    url,
    headers: authHeaders(),
    json: true,
  });
  return (res && res.users) || [];
}

function dateStr(d, tz) {
  // Convertit une date/heure absolue en chaîne YYYY-MM-DD selon le fuseau
  // Toronto, quel que soit le fuseau horaire du serveur qui exécute ce code.
  return new Date(d).toLocaleDateString("en-CA", { timeZone: tz });
}

function addDaysToDateStr(ymd, days) {
  // Arithmétique purement calendaire (Y-M-D) sur une chaîne déjà exprimée
  // dans le fuseau Toronto : évite tout décalage lié au fuseau horaire du
  // serveur n8n (Date.setDate() opère en heure locale du serveur, pas
  // forcément Toronto).
  const [y, m, d] = ymd.split("-").map(Number);
  const utcDate = new Date(Date.UTC(y, m - 1, d));
  utcDate.setUTCDate(utcDate.getUTCDate() + days);
  return utcDate.toISOString().slice(0, 10);
}

const priorityLabels = { low: "Basse", medium: "Moyenne", high: "Haute" };

const todayStr = dateStr(new Date(), TZ);
const weekStartStr = todayStr;
const weekEndStr = addDaysToDateStr(todayStr, 6);
const lastWeekStartStr = addDaysToDateStr(todayStr, -7);

function renderTaskList(list) {
  if (!list || list.length === 0) return "<p style=\"color:#888;\">Aucune</p>";
  const items = list
    .map(
      (t) =>
        `<li>${t.title} (priorité : ${priorityLabels[t.priority] || t.priority})</li>`
    )
    .join("");
  return `<ul>${items}</ul>`;
}

function renderMeetingList(list) {
  if (!list || list.length === 0) return "<p style=\"color:#888;\">Aucune</p>";
  const items = list
    .map((m) => `<li>${m.title} — ${new Date(m.starts_at).toLocaleString("fr-CA")}</li>`)
    .join("");
  return `<ul>${items}</ul>`;
}

function renderProgressList(list) {
  if (!list || list.length === 0) return "<p style=\"color:#888;\">Aucun projet</p>";
  const items = list
    .map((p) => `<li>${p.title} — ${p.done}/${p.total} tâches terminées (${p.pct}%)</li>`)
    .join("");
  return `<ul>${items}</ul>`;
}

function buildEmail(data) {
  const linkHtml = data.appBaseUrl
    ? `<p><a href="${data.appBaseUrl}/" style="color:#2563eb;">Ouvrir ProjectFlow</a></p>`
    : "";

  const html = `
    <div style="font-family:Arial,sans-serif;color:#111;max-width:600px;">
      <h2 style="color:#2563eb;">ProjectFlow — Rapport hebdomadaire d'avancement</h2>
      <p>Résumé de la semaine écoulée et aperçu de la semaine à venir.</p>

      <h3>Projets actifs (${data.activeProjects.length})</h3>
      <ul>${data.activeProjects.map((p) => `<li>${p.title}</li>`).join("") || "<li style=\"color:#888;\">Aucun</li>"}</ul>

      <h3>Tâches créées cette semaine (${data.tasksCreated.length})</h3>
      ${renderTaskList(data.tasksCreated)}

      <h3>Tâches terminées (${data.tasksDone.length})</h3>
      ${renderTaskList(data.tasksDone)}

      <h3>Tâches restantes (${data.tasksRemaining.length})</h3>
      ${renderTaskList(data.tasksRemaining)}

      <h3>Tâches en retard (${data.tasksOverdue.length})</h3>
      ${renderTaskList(data.tasksOverdue)}

      <h3>Échéances de la semaine (${data.deadlinesThisWeek.length})</h3>
      ${renderTaskList(data.deadlinesThisWeek)}

      <h3>Réunions de la semaine (${data.meetingsThisWeek.length})</h3>
      ${renderMeetingList(data.meetingsThisWeek)}

      <h3>Progression des projets</h3>
      ${renderProgressList(data.progressByProject)}

      ${linkHtml}
      <p style="color:#888;font-size:12px;">Cet e-mail est un canal complémentaire aux notifications internes ProjectFlow. Rapport généré automatiquement, sans appel à un service d'IA.</p>
    </div>
  `;

  return { email: data.email, subject: "ProjectFlow — Rapport hebdomadaire d'avancement", html };
}

const users = await listAuthUsers.call(this);
const results = [];

for (const user of users) {
  if (!user.email) continue; // pas d'adresse exploitable, on ignore cet utilisateur

  try {
    const [projects, tasks, meetings] = await Promise.all([
      restGet.call(this, "projects", { user_id: `eq.${user.id}`, select: "id,title,status,deadline" }),
      restGet.call(this, "tasks", {
        user_id: `eq.${user.id}`,
        select: "id,title,status,priority,due_date,created_at,project_id",
      }),
      restGet.call(this, "meetings", {
        user_id: `eq.${user.id}`,
        select: "id,title,starts_at,project_id",
      }),
    ]);

    const activeProjects = projects.filter((p) => p.status === "active");

    const tasksCreated = tasks.filter((t) => {
      const created = dateStr(t.created_at, TZ);
      return created >= lastWeekStartStr && created <= todayStr;
    });

    const tasksDone = tasks.filter((t) => t.status === "done");
    const tasksRemaining = tasks.filter((t) => t.status !== "done");
    const tasksOverdue = tasks.filter((t) => {
      if (t.status === "done" || !t.due_date) return false;
      return dateStr(t.due_date, TZ) < todayStr;
    });

    const deadlinesThisWeek = tasks.filter((t) => {
      if (!t.due_date) return false;
      const d = dateStr(t.due_date, TZ);
      return d >= weekStartStr && d <= weekEndStr;
    });

    const meetingsThisWeek = meetings.filter((m) => {
      if (!m.starts_at) return false;
      const d = dateStr(m.starts_at, TZ);
      return d >= weekStartStr && d <= weekEndStr;
    });

    const progressByProject = projects.map((p) => {
      const projectTasks = tasks.filter((t) => t.project_id === p.id);
      const total = projectTasks.length;
      const done = projectTasks.filter((t) => t.status === "done").length;
      const pct = total > 0 ? Math.round((done / total) * 100) : 0;
      return { title: p.title, done, total, pct };
    });

    results.push({
      json: buildEmail({
        email: user.email,
        activeProjects,
        tasksCreated,
        tasksDone,
        tasksRemaining,
        tasksOverdue,
        deadlinesThisWeek,
        meetingsThisWeek,
        progressByProject,
        appBaseUrl: APP_BASE_URL,
      }),
    });
  } catch (err) {
    // Une erreur pour cet utilisateur ne doit pas empêcher la génération des
    // rapports des autres utilisateurs : on journalise et on continue la boucle,
    // sans ajouter d'item pour cet utilisateur (donc aucun e-mail malformé envoyé).
    console.error(
      `[weekly-progress-report] Échec de génération du rapport pour ${user.email}:`,
      err
    );
    continue;
  }
}

return results;
